<?php declare(strict_types=1); namespace DockerManger; final class Compose {public function __construct(private string $root){} public function stacks():array{$r=[];foreach(glob(rtrim($this->root,'/').'/*',GLOB_ONLYDIR)?:[] as $d)foreach(['compose.yaml','compose.yml','docker-compose.yml','docker-compose.yaml'] as $f)if(is_file("$d/$f")){$r[]=['name'=>basename($d),'file'=>$f];break;}return$r;}}